extracted_python_code:
frequently_bought_stocks = Tickers.CALCULATE(
    ticker_symbol=symbol,
    num_buy_transactions=COUNT(
        transactions_of.WHERE(
            (DATEDIFF("days", date_time, DATETIME('now')) <= 10) & 
            (transaction_type == "buy")
        )
    )
).TOP_K(2, by=num_buy_transactions.DESC())

activity_ratio_by_country = Customers.WHERE(
    (YEAR(join_date) == 2022) & (HAS(transactions_made) == 1)
).PARTITION(name="countries", by=(country)).CALCULATE(
    country=country,
    num_active_customers=COUNT(Customers.WHERE(status == 'active')),
    total_customers=COUNT(Customers)
).CALCULATE(
    country=country,
    AR=IFF(total_customers > 0, (num_active_customers / total_customers) * 100.0, 0.0)
)

result = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (
                STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')
            ) & 
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Tickers.WHERE(
    HAS(transactions_of.WHERE(
        (transaction_type == "sell") & 
        (DATEDIFF("days", date_time, DATETIME("now")) <= 30)
    )) == 1
).CALCULATE(
    ticker_symbol=symbol,
    spm=100.0 * (
        SUM(transactions_of.WHERE(
            (transaction_type == "sell") & 
            (DATEDIFF("days", date_time, DATETIME("now")) <= 30)
        ).amount) - 
        SUM(transactions_of.WHERE(
            (transaction_type == "sell") & 
            (DATEDIFF("days", date_time, DATETIME("now")) <= 30)
        ).CALCULATE(total_costs=tax + commission).total_costs)
    ) / SUM(transactions_of.WHERE(
        (transaction_type == "sell") & 
        (DATEDIFF("days", date_time, DATETIME("now")) <= 30)
    ).amount)
)

distinct_customer_ids = Transactions.WHERE(
    transaction_type == 'buy'
).PARTITION(
    name="customers", by=(customer_id)
).CALCULATE(
    customer_id=customer_id
)

distinct_ticker_ids = DailyPrices.WHERE(date >= "2023-04-01").PARTITION(name="distinct_tickers", by=ticker_id).CALCULATE(
    ticker_id=ticker_id
)

transactions_in_last_30_days = Transactions.WHERE(
    DATEDIFF("days", date_time, DATETIME('now')) <= 30
)

country_transactions = transactions_in_last_30_days.CALCULATE(
    country=customer.country
)

country_summary = country_transactions.PARTITION(
    name="country_groups", by=(country)
).CALCULATE(
    country_name=country,
    number_of_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
)

top_countries_by_amount = country_summary.TOP_K(
    5, by=total_transaction_amount.DESC()
)

lowest_price_vti = Broker.CALCULATE(
    lowest_daily_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == 'VTI') & (DATEDIFF("days", date, 'now') <= 7)
        ).close
    )
)

result = Broker.CALCULATE(
    num_transactions=COUNT(Transactions.WHERE(DATEDIFF("days", customer.join_date, 'now') <= 70))
)

monthly_average_prices = Transactions.WHERE(
    (status == 'success') &
    (YEAR(date_time) == 2023) &
    ISIN(MONTH(date_time), (1, 2, 3))
).CALCULATE(
    transaction_month=MONTH(date_time)
).PARTITION(
    name="monthly_groups", by=(transaction_month)
).CALCULATE(
    month=transaction_month,
    average_price=AVG(Transactions.price)
).ORDER_BY(month.ASC())

sales_by_model = Cars.WHERE(
    LIKE(UPPER(vin_number), '%M5%')
).PARTITION(
    name="model_group", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    number_of_sales=COUNT(Cars.sale_records)
)

result = Dealership.CALCULATE(
    asp=AVG(Sales.WHERE((YEAR(sale_date) == 2023) & (MONTH(sale_date) <= 3)).sale_price)
)

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ),
        2
    )
)

total_sales_count = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, 'now') < 7))
)

result = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

salespersons_with_cash_payments = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == 'Cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

result = Dealership.CALCULATE(
    num_payments=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == 'Utility Company') & 
            ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday'))
        )
    )
)

result = Drugs.WHERE(
    HAS(treatments_used_in.WHERE(~(end_dt == None))) == 1
).CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(
            ~(end_dt == None)
        ).CALCULATE(
            ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd
    )
)

result = DermTreatment.CALCULATE(
    num_patients=COUNT(Patients.WHERE(ENDSWITH(email, '@gmail.com') | ENDSWITH(email, '@yahoo.com')))
)

distinct_patient_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & 
                    (drug.drug_type == 'biologic')
                )
            ) == 1
        )
    )
)

alice_treatments_last_6_months = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(first_name == 'Alice').treatments_received.WHERE(
            (start_dt >= DATETIME('now', 'start of month', '-6 months')) & (start_dt < DATETIME('now', 'start of month'))
        )
    )
)

result = DermTreatment.CALCULATE(
    average_weight=AVG(Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg)
)

male_patient_caw = DermTreatment.CALCULATE(
    CAW=AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

private_insured_patient_count = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((gender == 'female') & (ins_type == 'private')))
)

result = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(drug.drug_type == "Biologic")) == 1
).PARTITION(name="states", by=(loc_state,)).CALCULATE(
    state=loc_state
)

insurance_type_performance = Treatments.WHERE(
    YEAR(end_dt) == 2022
).CALCULATE(
    insurance_type=patient.ins_type
).PARTITION(
    name="insurance_groups", by=insurance_type
).CALCULATE(
    ins_type=insurance_type,
    avg_pasi_score=AVG(Treatments.outcome_records.day100_pasi_score),
    num_distinct_patients=NDISTINCT(Treatments.patient.patient_id)
).TOP_K(
    5, by=avg_pasi_score.ASC()
)

top_specialties_by_drug_amount = Treatments.WHERE(
    start_dt >= DATETIME('now', '-6 months')
).CALCULATE(
    doc_speciality=doctor.speciality
).PARTITION(
    name="specialties", by=(doc_speciality)
).CALCULATE(
    speciality=doc_speciality,
    number_of_treatments=COUNT(Treatments),
    total_drug_amount=SUM(Treatments.tot_drug_amt)
).TOP_K(
    3, by=total_drug_amount.DESC()
)

first_treatment_by_recent_doctors = Doctors.WHERE(
    year_reg == YEAR(DATETIME('now')) - 2
).prescribed_treatments.WHERE(
    RANKING(by=start_dt.ASC(), per="Doctors") == 1
).CALCULATE(
    last_name=doctor.last_name,
    year_reg=doctor.year_reg,
    first_treatment_id=treatment_id,
    first_treatment_date=start_dt
)

avg_patient_age = DermTreatment.CALCULATE(
    average_age=AVG(
        Patients.WHERE(
            (gender == 'male') & (ins_type == 'private')
        ).CALCULATE(
            age=DATEDIFF("years", date_of_birth, DATETIME('now'))
        ).age
    )
)

active_retail_merchants_with_coupons = Merchants.WHERE(
    (status == 'active') & (LOWER(category) == 'retail') & (HAS(coupons) == 1)
).CALCULATE(
    merchant_name=name,
    total_coupons=COUNT(coupons)
)

user_session_duration_analysis = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration
    )
).WHERE(
    total_duration > 0
).ORDER_BY(
    total_duration.DESC()
)

result = Users.WHERE(LOWER(country) == 'us').CALCULATE(
    username=username,
    unread_promo_notifications=COUNT(
        notifications.WHERE(
            (notification_type == 'promotional') & (status == 'unread')
        )
    )
).WHERE(unread_promo_notifications > 0)

distinct_merchant_receivers = Transactions.WHERE(receiver_type == 1).PARTITION(name="merchants", by=(receiver_id)).CALCULATE(
    merchant_id=receiver_id
)

result = Ewallet.CALCULATE(
    median_merchant_balance=MEDIAN(
        Merchants.WHERE(
            (status == 'active') & CONTAINS(category, 'retail')
        ).balances.WHERE(
            updated_at >= DATETIME('now', 'start of day')
        ).balance
    )
)

result = Ewallet.CALCULATE(
    min_date_2023=MIN(UserSettingSnapshots.WHERE(YEAR(snapshot_date) == 2023).snapshot_date)
).CALCULATE(
    avg_tx_limit_daily=AVG(UserSettingSnapshots.WHERE(snapshot_date == min_date_2023).tx_limit_daily),
    avg_tx_limit_monthly=AVG(UserSettingSnapshots.WHERE(snapshot_date == min_date_2023).tx_limit_monthly)
)
